import React, { useEffect, useState, useRef, useCallback } from "react";
import { useParams, useNavigate } from "react-router-dom";
import axios from "axios";
import { io } from "socket.io-client";
import { useAuth } from "../context/AuthContext";
import "./Chat.css";

let socket;

export default function Chat() {
  const { userId } = useParams();
  const { user } = useAuth();
  const navigate = useNavigate();
  const [conversations, setConversations] = useState([]);
  const [messages, setMessages] = useState([]);
  const [activeUser, setActiveUser] = useState(null);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const [convLoading, setConvLoading] = useState(true);
  const bottomRef = useRef(null);
  const activeUserRef = useRef(null);

  // Keep ref in sync with state
  useEffect(() => {
    activeUserRef.current = activeUser;
  }, [activeUser]);

  // Connect socket ONCE
  useEffect(() => {
    socket = io("http://localhost:5000");
    socket.emit("join", user._id);

    socket.on("receiveMessage", ({ senderId, message, timestamp }) => {
      // Only add if this is the active conversation
      if (activeUserRef.current?._id === senderId) {
        setMessages((prev) => [
          ...prev,
          { sender: { _id: senderId }, content: message, createdAt: timestamp },
        ]);
      }
    });

    return () => socket.disconnect();
  }, [user._id]);

  // Load conversations list
  const loadConversations = useCallback(async () => {
    try {
      const { data } = await axios.get("/api/messages/conversations");
      setConversations(data);
    } catch (err) {
      console.error("Failed to load conversations", err);
    } finally {
      setConvLoading(false);
    }
  }, []);

  useEffect(() => {
    loadConversations();
  }, [loadConversations]);

  // Open a conversation
  const openConversation = useCallback(async (targetUser) => {
    if (!targetUser?._id) return;
    setActiveUser(targetUser);
    setLoading(true);
    navigate(`/chat/${targetUser._id}`, { replace: true });
    try {
      const { data } = await axios.get(`/api/messages/${targetUser._id}`);
      setMessages(data);
    } catch (err) {
      console.error("Failed to load messages", err);
    } finally {
      setLoading(false);
    }
  }, [navigate]);

  // Auto-open from URL param (e.g. coming from mentor profile)
  useEffect(() => {
    if (!userId) return;
    if (activeUser?._id === userId) return;

    axios.get(`/api/users/${userId}`)
      .then((res) => openConversation(res.data))
      .catch((err) => console.error("User not found", err));
  }, [userId, openConversation]);

  // Scroll to bottom when messages change
  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const sendMessage = async () => {
    if (!input.trim() || !activeUser) return;
    const content = input.trim();
    setInput("");

    // Optimistic UI update
    setMessages((prev) => [
      ...prev,
      { sender: { _id: user._id }, content, createdAt: new Date() },
    ]);

    try {
      // FIXED: using /send route now
      await axios.post("/api/messages/send", {
        receiverId: activeUser._id,
        content,
      });

      // Emit socket for real-time
      socket.emit("sendMessage", {
        senderId: user._id,
        receiverId: activeUser._id,
        message: content,
      });

      // Refresh conversations to update last message
      loadConversations();
    } catch (err) {
      console.error("Failed to send message", err);
    }
  };

  const handleKey = (e) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      sendMessage();
    }
  };

  return (
    <div className="chat-page">
      {/* Sidebar */}
      <div className="chat-sidebar">
        <div className="chat-sidebar-header">
          <h3>Messages</h3>
        </div>

        {convLoading ? (
          <div className="spinner" style={{ margin: "20px auto" }} />
        ) : conversations.length === 0 ? (
          <div className="chat-empty-sidebar">
            <p>No conversations yet.</p>
            <p style={{ fontSize: 12 }}>
              Start by messaging a mentor from their profile!
            </p>
          </div>
        ) : (
          conversations.map(({ partner, lastMessage }) => (
            <div
              key={partner._id}
              className={`conv-item ${activeUser?._id === partner._id ? "active" : ""}`}
              onClick={() => openConversation(partner)}
            >
              <div className="conv-avatar">{partner.name?.[0]}</div>
              <div className="conv-info">
                <div className="conv-name">{partner.name}</div>
                <div className="conv-last">
                  {lastMessage?.content?.slice(0, 30)}
                  {lastMessage?.content?.length > 30 ? "..." : ""}
                </div>
              </div>
              <div
                className={`role-badge ${partner.role}`}
                style={{ fontSize: 10, padding: "2px 6px" }}
              >
                {partner.role}
              </div>
            </div>
          ))
        )}
      </div>

      {/* Chat area */}
      <div className="chat-main">
        {!activeUser ? (
          <div className="chat-placeholder">
            <span>💬</span>
            <h3>Select a conversation</h3>
            <p>
              Choose from your conversations or start a new one from a
              mentor's profile.
            </p>
          </div>
        ) : (
          <>
            <div className="chat-header">
              <div className="conv-avatar">{activeUser.name?.[0]}</div>
              <div>
                <div className="chat-header-name">{activeUser.name}</div>
                <div className="chat-header-role">
                  {activeUser.role} • {activeUser.domain || ""}
                </div>
              </div>
            </div>

            <div className="messages-area">
              {loading ? (
                <div className="spinner" style={{ margin: "40px auto" }} />
              ) : messages.length === 0 ? (
                <div className="no-messages">
                  Send a message to start the conversation!
                </div>
              ) : (
                messages.map((msg, i) => {
                  const isMe =
                    msg.sender?._id === user._id ||
                    msg.sender?._id?.toString() === user._id?.toString() ||
                    msg.sender === user._id;
                  return (
                    <div
                      key={i}
                      className={`message-wrap ${isMe ? "me" : "them"}`}
                    >
                      {!isMe && (
                        <div className="msg-avatar">
                          {activeUser.name?.[0]}
                        </div>
                      )}
                      <div
                        className={`message-bubble ${isMe ? "me" : "them"}`}
                      >
                        {msg.content}
                        <div className="msg-time">
                          {new Date(msg.createdAt).toLocaleTimeString([], {
                            hour: "2-digit",
                            minute: "2-digit",
                          })}
                        </div>
                      </div>
                    </div>
                  );
                })
              )}
              <div ref={bottomRef} />
            </div>

            <div className="chat-input-area">
              <textarea
                className="chat-input"
                rows={1}
                placeholder="Type a message... (Enter to send)"
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={handleKey}
              />
              <button className="btn-primary send-btn" onClick={sendMessage}>
                Send ↑
              </button>
            </div>
          </>
        )}
      </div>
    </div>
  );
}
